local UIFishPoolHangUpSettingInfoNode = Class("UIFishPoolHangUpSettingInfoNode")
function UIFishPoolHangUpSettingInfoNode:__init() 
    self._queueId = nil      --队列id
    self._fishPlaceId = nil  --钓场id
    self._allBuff = {}       --所有的buff加成
    self._closeCb = nil

    self._maxNum = 1         --最大数量
    self._curNum = 0         --当前的数量
end

function UIFishPoolHangUpSettingInfoNode:__delete()
    self._queueId = nil
    self._fishPlaceId = nil 
    self._allBuff = nil       --所有的buff加成
    self._closeCb = nil
    self._maxNum = nil
    self._curNum = nil         --当前的数量
end

function UIFishPoolHangUpSettingInfoNode:Awake()    
end

function UIFishPoolHangUpSettingInfoNode:Start()
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnClose))
    SetButtonAction(self.FontStyleButtonSetting, Bind(self, self.OnBtnBeginHangUp))
    SetButtonAction(self.Btnadd, Bind(self, self.OnBtnAdd))
    SetButtonAction(self.Btnsubtract, Bind(self, self.OnBtnReduce))
    SetButtonAction(self.MaxButton, Bind(self, self.OnMaxButton))
    SetButtonAction(self.MinButton, Bind(self, self.OnMinButton))

    self.InputField.onValueChanged:AddListener(function(num)
        num = checkNumber(num)
        if num <= 0 then
            self._curNum = 0
        elseif num >= self._maxNum then
            self._curNum = self._maxNum
        else
            self._curNum = num    
        end
        self:RefreshSelectNum()
    end)

    self.FontStyleButtonSetting:ResetFontStyle("B1", localize("开始挂机"))
end

function UIFishPoolHangUpSettingInfoNode:Refresh(queueId, fishPlaceId, cb, refreshCb)
    if not queueId or not fishPlaceId then
        return
    end
    self._queueId = checkNumber(queueId)
    self._fishPlaceId = checkNumber(fishPlaceId)
    self._closeCb = cb
    self._cb = refreshCb

    self._maxNum = FishingUtils.GetMaxHangUpNum(queueId)
    self:FillSelf()
end

function UIFishPoolHangUpSettingInfoNode:FillSelf()
    local vo = FishingUtils.GetFishingPlaceVo(self._fishPlaceId)
    if vo then
        CfUtils.FillText(self.TxtTitle1, vo.name)
    end

    self:RefreshBuffList()
    self:RefreshSelectNum()
end

--初始化buff数据
function UIFishPoolHangUpSettingInfoNode:InitBuffData()
    local t1 = {}
    local dojo = FishingUtils.GetHangUpDojoByQueueId(self._queueId)
    if not dojo then
        return
    end
    if string.isEmpty(checkString(dojo.cards)) then
        return
    end
    
    local t = CfUtils.Split(dojo.cards, ",")
    for k, id in pairs(t) do
        local buffData = FishingUtils.GetActiveCardBuffData(id, Constants.ChooseCardStatus.FishHangeUp) 
        for _, v in pairs(buffData) do
            table.insert(t1, v)
        end
    end
    --[[
    self._allBuff = {}
    local t2 = {}
    for k, v in pairs(t1) do
        if t2[checkString(v.buffData.type)] then
            t2[checkString(v.buffData.type)].value = t2[checkString(v.buffData.type)].value + checkNumber(v.buffData.value)
        else
            t2[checkString(v.buffData.type)] = {
                value = checkNumber(v.buffData.value),
                buffData = v.buffData
            } 
        end
    end

    for k, v in pairs(t2) do
        table.insert(self._allBuff, {
            value = v.value,
            buffData = v.buffData
        })
    end
    ]]
    self._allBuff = FishingUtils.GetBuffTotalValueData(t1)
end

--刷新bufflist
function UIFishPoolHangUpSettingInfoNode:RefreshBuffList()
    self:InitBuffData()
    if self._isInitList then
        GameUtils.ReloadData(self.LoopListBonus, table.count(self._allBuff))
    else
        self.LoopListBonus:InitListView(table.count(self._allBuff), Bind(self, self.OnRefreshIndex))
        self._isInitList = true
    end
end

function UIFishPoolHangUpSettingInfoNode:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("InfoBar")
    local data = self._allBuff[index + 1]

    local Txt1Go = cell.gameObject.transform:Find("Txt1")
    local Txt2Go = cell.gameObject.transform:Find("Txt2")

    local addName = "+"
    local vo = FishingUtils.GetFishingBonusEffectVo(data.buffData.type)
    if vo then
        addName = (checkNumber(vo.isMinus) == 1 and "-" or "+")
    end

    local desc = FishingUtils.GetAdditionDesc(data.buffData) 
    CfUtils.FillText(Txt2Go, addName..checkInt(data.value * 100).."%")
    CfUtils.FillText(Txt1Go, FishingUtils.GetAdditionNoValueDesc(data.buffData, nil, true))

    return cell
end

--刷新数量
function UIFishPoolHangUpSettingInfoNode:RefreshSelectNum()
    self.InputField.text = self._curNum
    self:RefreshConsumesInfo()

    if self._cb then
        self._cb(self._curNum)    
    end
end

--刷新消耗信息
function UIFishPoolHangUpSettingInfoNode:RefreshConsumesInfo()
    local t = FishingUtils.GetHangUpConsumes(self._fishPlaceId)
    --[[
    table.insert(t, {
        goodsId = Constants.Currency.EnergyId,
        num = FishingUtils.GetFishHangUpEnergyNum(),
    })
    ]]

    for k, v in pairs(t) do
        local go = self.controller.gameObject.transform:Find("Consumption"..k)
        if go then
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(v.goodsId)
            if vo then
                CfUtils.FillText(go.transform:Find("Txt1"), localize("消耗_name_", {_name_ = vo.name}))
                CfUtils.FillImage(go.transform:Find("consumes/icon"), vo.photoPath)
                if k == 1 then
                    --CfUtils.FillImage(self.Imgicon, vo.photoPath)
                end
            end

            local num = 0
            --金币 总量的向下取整
            if checkNumber(v.goodsId) == Constants.Currency.GoldId then
                num = FishingUtils.GetQueueGoldConsume(self._queueId)
            end
            CfUtils.FillText(go.transform:Find("consumes/num"), math.floor(v.num * self._curNum * (1 - num)))
            KTool.SetActive(go, true)
        end
        if k == 1 then
            --CfUtils.FillText(self.TxtNum, v.num * self._curNum)
        end
    end

    local go = self.controller.gameObject.transform:Find("Consumption2")
    if go then
        CfUtils.FillText(go.transform:Find("consumes/num"), FishingUtils.GetFishHangUpEnergyNum() * self._curNum)
        CfUtils.FillText(go.transform:Find("Txt1"), localize("消耗精力"))
        KTool.SetActive(go, true)
    end

    --绘制时间
    local go = self.controller.gameObject.transform:Find("Consumption3")
    if go then
        local time = FishingUtils.GetFishHangUpTime() * self._curNum
        CfUtils.FillText(go.transform:Find("Txttime"), CfUtils.GetTimeHMS2(time))
        CfUtils.FillText(go.transform:Find("Txtconsumption"), localize("消耗时间"))
        KTool.SetActive(go, true)
    end
end

--增加
function UIFishPoolHangUpSettingInfoNode:OnBtnAdd()
    if self._curNum >= self._maxNum then
        GameUtils.Toast(localize("已经最大数量了"))
        return 
    end
    self._curNum = self._curNum + 1
    self:RefreshSelectNum()
end

--减少
function UIFishPoolHangUpSettingInfoNode:OnBtnReduce()
    if self._curNum <= 0 then
        GameUtils.Toast(localize("已经最低数量了"))
        return 
    end
    self._curNum = self._curNum - 1
    self:RefreshSelectNum()
end

--最多
function UIFishPoolHangUpSettingInfoNode:OnMaxButton()
    self._curNum = self._maxNum
    self:RefreshSelectNum()
end

--最少
function UIFishPoolHangUpSettingInfoNode:OnMinButton()
    self._curNum = 0
    self:RefreshSelectNum()
end

--开始挂机
function UIFishPoolHangUpSettingInfoNode:OnBtnBeginHangUp()
    if self._curNum <= 0 then
        GameUtils.Toast(localize("挂机次数不足"))
        return
    end
    fishingComponent:FishingOfflineStartReq(self._fishPlaceId, self._queueId, self._curNum, function()
        local t = FishingUtils.GetHangUpConsumes(self._fishPlaceId)
        for k, v in pairs(t) do
            local num = v.num
            --值扣金币
            if checkNumber(v.goodsId) == Constants.Currency.GoldId then
                num = FishingUtils.GetQueueGoldConsume(self._queueId)
                local rewards = {
                    {goodsId = v.goodsId, num = math.floor(v.num * self._curNum * (1 - num)) * -1}
                }
                GoodsUtils.DrawRewards(rewards)
            end
        end
    end)
end

function UIFishPoolHangUpSettingInfoNode:OnBtnClose()
    if self._closeCb then 
        self._closeCb()
    end
end

function UIFishPoolHangUpSettingInfoNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFishPoolHangUpSettingInfoNode
